package cn.paletale.companion;
import com.google.gson.*;
import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
/** Isolated server: exercises pagination and incomplete identity data without touching real favorites. */
final class FavoritePresenceHttpTest {
 static void run()throws Exception{
  var requests=new AtomicInteger();var totalRows=new AtomicInteger(49);var incomplete=new AtomicBoolean();var duplicate=new AtomicBoolean();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/api/mcmod/world/favorites",exchange->{requests.incrementAndGet();if(!exchange.getRequestURI().getRawQuery().contains("view=all"))throw new AssertionError("online status must never use network");int page=1;for(String part:exchange.getRequestURI().getRawQuery().split("&"))if(part.startsWith("page="))page=Integer.parseInt(part.substring(5));int total=totalRows.get();var json=new JsonObject();json.addProperty("version",1);json.addProperty("total",total);json.addProperty("page",page);json.addProperty("complete",!incomplete.get());var rows=new JsonArray();for(int i=(page-1)*48;i<Math.min(page*48,total);i++){var row=new JsonObject();row.addProperty("uuid",String.format(java.util.Locale.ROOT,"%032x",duplicate.get()&&page==2?1:i+1));row.addProperty("name","Player"+i);row.addProperty("current",true);row.addProperty("eligible",i!=0);rows.add(row);}json.add("players",rows);byte[] body=json.toString().getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,body.length);try(var out=exchange.getResponseBody()){out.write(body);}});server.start();
  try{var site=URI.create("http://127.0.0.1:"+server.getAddress().getPort());var watch=new FavoritePresenceWatch();var rows=watch.load(site,"fixture","all",1,new LinkedHashMap<>(),new HashSet<>(),-1).get(10,TimeUnit.SECONDS);if(rows.size()!=49||requests.get()!=2||FavoritePresenceWatch.indexed(rows).size()!=49)throw new AssertionError("correct paginated UUID favorites");int count=requests.get();String id=String.format(java.util.Locale.ROOT,"%032x",1);Object connection=new Object();var connectionField=FavoritePresenceWatch.class.getDeclaredField("connection");connectionField.setAccessible(true);connectionField.set(watch,connection);var indexedField=FavoritePresenceWatch.class.getDeclaredField("favoriteIds");indexedField.setAccessible(true);indexedField.set(watch,FavoritePresenceWatch.indexed(rows));var dirtyField=FavoritePresenceWatch.class.getDeclaredField("rosterDirty");dirtyField.setAccessible(true);watch.rosterChanged(connection,java.util.UUID.randomUUID());if(dirtyField.getBoolean(watch))throw new AssertionError("unrelated player must not schedule a scan");watch.rosterChanged(new Object(),java.util.UUID.fromString("00000000-0000-0000-0000-000000000001"));if(dirtyField.getBoolean(watch))throw new AssertionError("old connection must not schedule a scan");watch.rosterChanged(connection,java.util.UUID.fromString("00000000-0000-0000-0000-000000000001"));if(dirtyField.getBoolean(watch))throw new AssertionError("non-connection objects cannot schedule a scan");watch.observe(rows,Map.of());for(int i=0;i<10000;i++)watch.observe(rows,(i&1)==0?Map.of(id,"Player0"):Map.of());if(requests.get()!=count||watch.queued()!=1020)throw new AssertionError("local activity performs no requests and queue remains bounded");
   var tokenField=FavoritePresenceWatch.class.getDeclaredField("token");tokenField.setAccessible(true);tokenField.set(watch,"fixture");var siteField=FavoritePresenceWatch.class.getDeclaredField("site");siteField.setAccessible(true);siteField.set(watch,site);var favoritesField=FavoritePresenceWatch.class.getDeclaredField("favorites");favoritesField.setAccessible(true);favoritesField.set(watch,rows);watch.rotateToken("renewed");if(watch.queued()!=1020||favoritesField.get(watch)!=rows||requests.get()!=count)throw new AssertionError("token renewal must retain cache without requests");var accountField=FavoritePresenceWatch.class.getDeclaredField("accountId");accountField.setAccessible(true);accountField.setLong(watch,42);watch.invalidate("another",site,7);if(watch.queued()!=1020)throw new AssertionError("other account cannot invalidate cache");watch.changed("fixture",site,42,id,"Player0",false);var changed=(Map<?,?>)favoritesField.get(watch);if(changed.containsKey(id)||requests.get()!=count||watch.queued()!=0)throw new AssertionError("favorite removal updates local cache with no extra request");watch.changed("fixture",site,42,id,"Player0",true);if(!((Map<?,?>)favoritesField.get(watch)).containsKey(id)||requests.get()!=count)throw new AssertionError("favorite addition updates local cache with no extra request");watch.invalidate("fixture",site,42);if(favoritesField.get(watch)==null||requests.get()!=count)throw new AssertionError("refresh retains cache while offline and does not request online status");watch.observe(rows,Map.of(id,"Player0"));if(watch.queued()!=0)throw new AssertionError("changed collection establishes silent baseline");incomplete.set(true);var saved=watch.load(site,"fixture","all",1,new LinkedHashMap<>(),new HashSet<>(),-1).get(10,TimeUnit.SECONDS);if(saved.size()!=49)throw new AssertionError("stored UUID remains usable while names are unresolved");duplicate.set(true);try{watch.load(site,"fixture","all",1,new LinkedHashMap<>(),new HashSet<>(),-1).get(10,TimeUnit.SECONDS);throw new AssertionError("duplicate pages must fail");}catch(java.util.concurrent.ExecutionException expected){}duplicate.set(false);incomplete.set(false);totalRows.set(1000);int beforeCapacity=requests.get();var maximum=watch.load(site,"fixture","all",1,new LinkedHashMap<>(),new HashSet<>(),-1).get(20,TimeUnit.SECONDS);if(maximum.size()!=1000||requests.get()-beforeCapacity!=21)throw new AssertionError("1000 favorites fit in 21 bounded pages");var initialWatch=new FavoritePresenceWatch();initialWatch.announceInitial(maximum);if(initialWatch.queued()!=1000)throw new AssertionError("all initial online favorites are queued without loss");var pending=(java.util.Collection<?>)WorldClientGameTest.field(initialWatch,"queue");if(pending.stream().map(FavoritePresenceWatch.Pending.class::cast).filter(FavoritePresenceWatch.Pending::sound).count()!=1)throw new AssertionError("initial online notices share one sound");initialWatch.advance(1000);initialWatch.advance(1250);if(initialWatch.queued()!=998)throw new AssertionError("initial notices begin together in a bounded stack");totalRows.set(1001);try{watch.load(site,"fixture","all",1,new LinkedHashMap<>(),new HashSet<>(),-1).get(10,TimeUnit.SECONDS);throw new AssertionError("over-capacity favorites must fail");}catch(java.util.concurrent.ExecutionException expected){}try{watch.load(site,"fixture","online",1,new LinkedHashMap<>(),new HashSet<>(),-1).get(10,TimeUnit.SECONDS);throw new AssertionError("online API must not be called");}catch(java.util.concurrent.ExecutionException expected){}System.out.println("FAVORITE PRESENCE: local changes use zero requests; UUID favorites bounded and paginated");}finally{server.stop(0);}
 }
}
